{
  "root": "main_stack",
  "state": {
    "savings_overview_data": [
      { "Key": "Goal", "Value": "$50,000" },
      { "Key": "Initial Savings", "Value": "$5,000" },
      { "Key": "Target Date", "Value": "August 1, 2027" },
      { "Key": "Months to Goal", "Value": "39 months (assuming current month is May 2024)" },
      { "Key": "Remaining to Save", "Value": "$45,000" },
      { "Key": "Required Monthly Savings", "Value": "~$1,154" },
      { "Key": "Current Monthly Surplus", "Value": "$1,500" }
    ],
    "milestones_data": [
      { "Milestone": "Start", "Target Date": "May 2024", "Cumulative Savings": "$5,000", "Focus": "Baseline" },
      { "Milestone": "6 Months", "Target Date": "Nov 2024", "Cumulative Savings": "$14,000", "Focus": "Automate Savings Transfer" },
      { "Milestone": "12 Months", "Target Date": "May 2025", "Cumulative Savings": "$23,000", "Focus": "Budget Review & Optimization" },
      { "Milestone": "24 Months", "Target Date": "May 2026", "Cumulative Savings": "$41,000", "Focus": "Explore Income Growth Opportunities" },
      { "Milestone": "Goal Achieved!", "Target Date": "Nov 2026", "Cumulative Savings": "$50,000", "Focus": "Research Housing Market & Lenders" },
      { "Milestone": "Target Date", "Target Date": "Aug 2027", "Cumulative Savings": "$63,500", "Focus": "Build Emergency Fund or Furnishing Budget" }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title",
        "intro_text",
        "overview_h2",
        "overview_intro_text",
        "savings_overview_table",
        "overview_summary_text",
        "roadmap_h2",
        "roadmap_intro_text",
        "milestones_h3",
        "milestones_intro_text",
        "milestones_table",
        "expense_optimization_section",
        "income_boosters_section",
        "quick_actions_h2",
        "budgeting_button",
        "savings_accounts_button",
        "sources_h2",
        "investopedia_button"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Your $50,000 House Down Payment Plan",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This plan outlines a clear path to achieve your $50,000 house down payment goal by August 1, 2027, leveraging your current financial situation and suggesting strategies for accelerated savings."
      },
      "children": []
    },
    "overview_h2": {
      "type": "Text",
      "props": {
        "text": "Savings Plan Overview",
        "variant": "h2"
      },
      "children": []
    },
    "overview_intro_text": {
      "type": "Text",
      "props": {
        "text": "Based on your provided details, you are well-positioned to reach and even exceed your down payment target."
      },
      "children": []
    },
    "savings_overview_table": {
      "type": "Table",
      "props": {
        "columns": [
          { "key": "Key", "label": "Key" },
          { "key": "Value", "label": "Value" }
        ],
        "statePath": "/savings_overview_data",
        "domain": "formula",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "overview_summary_text": {
      "type": "Text",
      "props": {
        "text": "You are currently saving $346 more per month than required to meet your goal, putting you on track to achieve it significantly earlier or with a larger down payment."
      },
      "children": []
    },
    "roadmap_h2": {
      "type": "Text",
      "props": {
        "text": "Detailed Savings Roadmap",
        "variant": "h2"
      },
      "children": []
    },
    "roadmap_intro_text": {
      "type": "Text",
      "props": {
        "text": "Your current monthly surplus of $1,500 means you can reach your $50,000 goal (including your initial $5,000) in approximately 30 months, which is by November 2026. This is 9 months ahead of your August 2027 target! This allows for a buffer or a larger down payment."
      },
      "children": []
    },
    "milestones_h3": {
      "type": "Text",
      "props": {
        "text": "Key Milestones",
        "variant": "h3"
      },
      "children": []
    },
    "milestones_intro_text": {
      "type": "Text",
      "props": {
        "text": "This roadmap illustrates your progress if you consistently save your current $1,500 monthly surplus."
      },
      "children": []
    },
    "milestones_table": {
      "type": "Table",
      "props": {
        "columns": [
          { "key": "Milestone", "label": "Milestone" },
          { "key": "Target Date", "label": "Target Date" },
          { "key": "Cumulative Savings", "label": "Cumulative Savings" },
          { "key": "Focus", "label": "Focus" }
        ],
        "statePath": "/milestones_data",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "Milestone",
        "highlightColumns": ["Cumulative Savings", "Focus"]
      },
      "children": []
    },
    "expense_optimization_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "expense_optimization_h3_with_icon",
        "expense_optimization_intro_text",
        "expense_optimization_list"
      ]
    },
    "expense_optimization_h3_with_icon": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "expense_optimization_icon",
        "expense_optimization_h3"
      ]
    },
    "expense_optimization_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/cash-coin.svg"
      },
      "children": []
    },
    "expense_optimization_h3": {
      "type": "Text",
      "props": {
        "text": "Expense Optimization",
        "variant": "h3"
      },
      "children": []
    },
    "expense_optimization_intro_text": {
      "type": "Text",
      "props": {
        "text": "Even though you are on track, optimizing expenses can provide a larger buffer or accelerate your goal further."
      },
      "children": []
    },
    "expense_optimization_list": {
      "type": "List",
      "props": {},
      "children": [
        "expense_food_text",
        "expense_subscriptions_text",
        "expense_transportation_text",
        "expense_discretionary_text"
      ]
    },
    "expense_food_text": {
      "type": "Text",
      "props": {
        "text": "Food: Reduce dining out frequency; plan meals and grocery lists; consider cooking at home more often."
      },
      "children": []
    },
    "expense_subscriptions_text": {
      "type": "Text",
      "props": {
        "text": "Subscriptions: Review all recurring subscriptions (streaming, apps, gym memberships) and cancel any unused services."
      },
      "children": []
    },
    "expense_transportation_text": {
      "type": "Text",
      "props": {
        "text": "Transportation: Explore carpooling, public transit, or consolidating errands to reduce fuel and maintenance costs."
      },
      "children": []
    },
    "expense_discretionary_text": {
      "type": "Text",
      "props": {
        "text": "Discretionary Spending: Set a strict budget for non-essential purchases like entertainment, shopping, and hobbies."
      },
      "children": []
    },
    "income_boosters_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "income_boosters_h3_with_icon",
        "income_boosters_intro_text",
        "income_boosters_list"
      ]
    },
    "income_boosters_h3_with_icon": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "income_boosters_icon",
        "income_boosters_h3"
      ]
    },
    "income_boosters_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/graph-up.svg"
      },
      "children": []
    },
    "income_boosters_h3": {
      "type": "Text",
      "props": {
        "text": "Income Boosters",
        "variant": "h3"
      },
      "children": []
    },
    "income_boosters_intro_text": {
      "type": "Text",
      "props": {
        "text": "Increasing your income can help you reach your goal even faster or provide additional funds for closing costs and home improvements."
      },
      "children": []
    },
    "income_boosters_list": {
      "type": "List",
      "props": {},
      "children": [
        "income_side_hustle_text",
        "income_overtime_text",
        "income_skill_dev_text",
        "income_selling_items_text"
      ]
    },
    "income_side_hustle_text": {
      "type": "Text",
      "props": {
        "text": "Side Hustle: Explore freelance work, gig economy jobs, or selling a skill you possess."
      },
      "children": []
    },
    "income_overtime_text": {
      "type": "Text",
      "props": {
        "text": "Overtime/Extra Shifts: If available at your current employment, consider taking on additional hours."
      },
      "children": []
    },
    "income_skill_dev_text": {
      "type": "Text",
      "props": {
        "text": "Skill Development: Invest in courses or certifications to qualify for promotions or higher-paying roles."
      },
      "children": []
    },
    "income_selling_items_text": {
      "type": "Text",
      "props": {
        "text": "Selling Unused Items: Declutter your home and sell items you no longer need."
      },
      "children": []
    },
    "quick_actions_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "budgeting_button": {
      "type": "Button",
      "props": {
        "label": "Explore Budgeting Tools"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.nerdwallet.com/article/finance/best-budgeting-apps"
          }
        }
      },
      "children": []
    },
    "savings_accounts_button": {
      "type": "Button",
      "props": {
        "label": "Compare High-Yield Savings Accounts"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.bankrate.com/banking/savings/best-high-yield-savings-accounts/"
          }
        }
      },
      "children": []
    },
    "sources_h2": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "investopedia_button": {
      "type": "Button",
      "props": {
        "label": "Investopedia: Down Payment"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.investopedia.com/terms/d/downpayment.asp"
          }
        }
      },
      "children": []
    }
  }
}
